  "helpOfficerAuditTitle": "చట్టపరమైన & ఆర్థిక ఆడిట్",
  "helpOfficerBannerDesc": "సహకార సంస్థల కోసం చట్టపరమైన సమ్మతి, ఫిర్యాదుల మధ్యవర్తిత్వం మరియు కార్మిక సంక్షేమ పోర్టల్.",
  "helpOfficerCasesDesc": "ਕਾਮਿਆਂ ਅਤੇ ਗਾਹਕਾਂ ਵਿਚਕਾਰ ਵਿਵਾਦਾਂ ਦੀ ਸੁਣਵਾਈ ਅਤੇ ਨਿਆਂਇਕ ਫੈਸਲੇ।",
