  "workerFlowStep5Title": "నైపుణ్యాలను మెరుగుపరుచుకోండి:",
  "workerHowItWorksDesc": "సహకార్ కనెక్ట్ వర్కర్ పోర్టల్ మిమ్మల్ని ఎటువంటి మధ్యవర్తులు లేకుండా నేరుగా సమీప కస్టమర్లతో కలుపుతుంది. మీరు పని అభ్యర్థనలను స్వీకరించవచ్చు, సురక్షితమైన OTPతో పనిని ప్రారంభించవచ్చు, తక్షణమే మీ ఖాతాలో వేతనం పొందవచ్చు మరియు సహకార సామాజిక భద్రతా ప్రయోజనాలను పొందవచ్చు.",
